import json
with open('batches/batch_0027.json') as f:
    data = json.load(f)

def fix(s):
    if not s:
        return s
    for enc in ('latin1','cp1252'):
        try:
            return s.encode(enc).decode('utf-8')
        except Exception:
            continue
    return s.encode('latin1','replace').decode('utf-8','replace')

targets = [1352,1355,1359,1363,1365,1367,1368,1373,1382,1383,1385,1391,1394,1395]
for d in data:
    if d['idx'] in targets:
        fb = fix(d.get('body',''))
        print('=== idx', d['idx'], d['name'], '===')
        print('BODY:', fb[:900])
        print()
"
